8	declare_rule! {
9	    /// Disallow invalid `!important` within keyframe declarations
10	    ///
11	    /// Using `!important` within keyframes declarations is completely ignored in some browsers.
12	    ///
13	    /// ## Examples
14	    ///
15	    /// ### Invalid
16	    ///
17	    /// ```css,expect_diagnostic
18	    /// @keyframes foo {
19	    ///     from {
20	    ///       opacity: 0;
21	    ///     }
22	    ///     to {
23	    ///       opacity: 1 !important;
24	    ///     }
25	    /// }
26	    /// ```
27	    ///
28	    /// ### Valid
29	    ///
30	    /// ```css
31	    /// @keyframes foo {
32	    ///     from {
33	    ///       opacity: 0;
34	    ///     }
35	    ///     to {
36	    ///       opacity: 1;
37	    ///     }
38	    /// }
39	    /// ```
40	    ///
41	    pub NoImportantInKeyframe {
42	        version: "next",
43	        name: "noImportantInKeyframe",
44	        recommended: true,
45	        sources:&[RuleSource::Stylelint("keyframe-declaration-no-important")],
46	    }
47	}
48	
49	impl Rule for NoImportantInKeyframe {
50	    type Query = Ast<CssKeyframesBlock>;
51	    type State = CssDeclarationImportant;
52	    type Signals = Option<Self::State>;
53	    type Options = ();
54	
55	    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
56	        let node = ctx.query();
57	        for item in node.items() {
58	            let AnyCssKeyframesItem::CssKeyframesItem(keyframe_item) = item else {
59	                return None;
60	            };
61	            let AnyCssDeclarationBlock::CssDeclarationBlock(block_declaration) =
62	                keyframe_item.block().ok()?
63	            else {
64	                return None;
65	            };
66	            for colon_declaration in block_declaration.declarations() {
67	                if let Some(important) = colon_declaration.declaration().ok()?.important() {
68	                    return Some(important);
69	                }
70	            }
71	        }
72	        None
73	    }
74	
75	    fn diagnostic(_ctx: &RuleContext<Self>, node: &Self::State) -> Option<RuleDiagnostic> {
76	        let span = node.range();
77	        Some(
78	            RuleDiagnostic::new(
79	                rule_category!(),
80	                span,
81	                markup! {
82	                    "Using "<Emphasis>"!important"</Emphasis>" within keyframes declaration is completely ignored in some browsers."
83	                },
84	            )
85	            .note(markup! {
86	                    "Consider removing useless "<Emphasis>"!important"</Emphasis>" declaration."
87	            }),
88	        )
89	    }
90	}
